    and c.del_flag='0'
    and c.case_status='pending'
    and c.case_status in ('processing','transfering')
    and (c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%') or c.contract_no like concat('%',#{keyword},'%') or c.main_lawyer_name like concat('%',#{keyword},'%'))
    and c.case_type=#{caseType}
    and c.urgency=#{urgency}
    and c.case_status=#{caseStatus}
    and c.main_lawyer_id=#{mainLawyerId}
    and c.contract_id=#{contractId}
    and c.contract_no like concat('%',#{contractNo},'%')


