mapper.update:
update biz_case
case_status=#{caseStatus}, current_node=#{currentNode}, main_lawyer_id=#{mainLawyerId}, main_lawyer_name=#{mainLawyerName}, update_by=#{updateBy}, update_time=sysdate()
where case_id=#{caseId} and del_flag='0' and case_status=#{expectedStatus}

update biz_lawyer_profile
set assign_enabled=#{assignEnabled}, update_by=#{updateBy}, update_time=sysdate()
where user_id=#{userId}

mapper.select:
select a.*, c.case_no caseNo,c.case_name caseName,c.customer_name customerName,c.case_type caseType,c.case_status caseStatus from biz_case_assignment a left join biz_case c on c.case_id=a.case_id
and c.del_flag='0' and (c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or a.main_lawyer_name like concat('%',#{keyword},'%')) and a.main_lawyer_id=#{mainLawyerId}
order by a.create_time desc

mapper.update:
update biz_case_transfer
set transfer_status=#{transferStatus}, current_node=#{currentNode}, approval_opinion=#{opinion}, approver_id=#{approverId}, approver_name=#{approverName}, update_by=#{updateBy}, update_time=sysdate()
where transfer_id=#{transferId} and transfer_status=#{expectedStatus}

mapper.select:
select t.*, c.case_no caseNo,c.case_name caseName,c.customer_name customerName,c.case_type caseType from biz_case_transfer t left join biz_case c on c.case_id=t.case_id
and c.del_flag='0' and (t.transfer_no like concat('%',#{keyword},'%') or c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or t.from_lawyer_name like concat('%',#{keyword},'%') or t.to_lawyer_name like concat('%',#{keyword},'%')) and t.transfer_status=#{transferStatus} and t.risk_level=#{riskLevel}
order by t.create_time desc

select cf.*, c.case_no caseNo,c.case_name caseName,c.customer_name customerName from biz_case_confirm cf left join biz_case c on c.case_id=cf.case_id
and c.del_flag='0' and (c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or cf.confirm_user_name like concat('%',#{keyword},'%')) and cf.confirm_status=#{confirmStatus}
order by cf.create_time desc

select l.*, c.case_no caseNo,c.case_name caseName from biz_case_status_log l left join biz_case c on c.case_id=l.case_id
and c.del_flag='0' and l.case_id=#{caseId}
order by l.create_time desc
